"""Focused publication rights, exact-content permission, private media and withdrawal tests."""
import base64,json,secrets,subprocess,requests
from pathlib import Path
import test_owner_workflow as workflow
class Publications(workflow.OwnerWorkflow):
 @classmethod
 def setUpClass(cls):
  super().setUpClass()
  for op in ['access','support','publication']:
   r=subprocess.run([cls.f.php,str(cls.f.path/('scripts/migrate-'+op+'.php')),'up'],capture_output=True,text=True)
   if r.returncode:raise RuntimeError(r.stderr)
 def setUp(self):
  for t in ['nd_publication_permission_events','nd_publication_permissions','nd_publication_versions','nd_publication_media','nd_publications','nd_order_access_policies']:self.f.sql('DELETE FROM '+t)
  super().setUp()
 def api(self,r,d=None,s=None,mode='owner'):
  s=s or self.owner;url=self.base+'/publication-api.php?mode='+mode+'&r='+r
  if d is None:return s.get(url)
  d.setdefault('request_key',secrets.token_hex(32));return s.post(url,json=d)
 def save(self,**extra):
  d={'kind':'portfolio','slug':'synthetic-'+secrets.token_hex(5),'order_id':None,'title':'SYNTHETIC portfolio','text':'SYNTHETIC owned example <script>window.LEAK=true</script>','display_name':'','media':[]};d.update(extra);return self.must(self.api('save',d))
 def publish(self,p,**extra):
  d={'id':int(p['record']['id']),'version':int(p['record']['version']),'checksum':p['head']['checksum'],'confirm':True,'own_materials_confirmed':True,'reason':'SYNTHETIC owner moderation','sort_order':2};d.update(extra);return self.api('publish',d)
 def test_owner_draft_media_publication_stale_versions_and_unpublish(self):
  png=base64.b64decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=');r=self.owner.post(self.base+'/publication-api.php?mode=owner&r=upload',files={'file':('SYNTHETIC.png',png,'image/png')});self.assertEqual(r.status_code,200,r.text);file=r.json()['file'];url=self.base+'/publication-api.php?r=media&id='+str(file['id']);self.assertEqual(requests.get(url).status_code,404);self.assertEqual(self.owner.post(self.base+'/publication-api.php?mode=owner&r=upload',files={'file':('bad.svg',b'<svg onload="alert(1)"/>','image/svg+xml')}).status_code,422)
  p=self.save(media=[{'id':int(file['id']),'caption':'SYNTHETIC caption'}]);self.assertEqual(self.api('items',mode='public').json()['items'],[]);self.assertEqual(self.publish(p,own_materials_confirmed=False).status_code,422);r=self.publish(p);self.assertEqual(r.status_code,200,r.text);self.assertEqual(requests.get(url).content,png);range_r=requests.get(url,headers={'Range':'bytes=0-7'});self.assertEqual(range_r.status_code,206);self.assertEqual(range_r.content,png[:8]);self.assertEqual(requests.get(url,headers={'Range':'bytes=999999-'}).status_code,416);item=self.api('items',mode='public').json()['items'][0];self.assertNotIn('order_id',item);self.assertIn('<script>',item['body']['text']);self.assertEqual(self.publish(p).status_code,409)
  current=r.json()['record'];new=self.save(id=int(current['id']),version=int(current['version']),title='SYNTHETIC changed head',text='SYNTHETIC new version not yet public',media=[]);self.assertEqual(self.api('items',mode='public').json()['items'][0]['body']['title'],'SYNTHETIC portfolio');off=self.api('unpublish',{'id':int(new['record']['id']),'version':int(new['record']['version']),'checksum':new['head']['checksum'],'confirm':True,'reason':'SYNTHETIC unpublish'});self.assertEqual(off.status_code,200,off.text);self.assertEqual(requests.get(url).status_code,404);self.assertEqual(self.api('media-list').json()['items'][0]['checksum'],file['checksum']);self.assertEqual(self.owner.get(url+'&mode=owner').content,png)
 def test_separate_paper_permission_scoped_exact_consent_and_withdrawal(self):
  oid,legacy,old_guest,values,terms=self.new_documents();p=self.save(order_id=oid);self.assertEqual(self.publish(p).status_code,409);self.f.sql("UPDATE nd_lc_order_flow SET delivery_state='HANDED_OVER' WHERE order_id=?",params=[oid]);prefill=self.api('version&version='+str(p['head']['id'])).json()['values'];values.update(prefill);terms=self.must(self.ctp('terms',order_id=oid,proposal_id=int(legacy[0]['id']),values=values,approved=True,confirm_terms=True))['id'];b=self.must(self.gen(self.templates[4],terms,applicable=True))['record'];asset=self.lg('documents/'+str(b['id'])).json()['record']['pdf'];self.must(self.ctp('review-pdf',binding_id=int(b['id']),pdf_checksum=asset['checksum'],confirm=True,reason='SYNTHETIC exact permission PDF review'));link=self.create_link(oid,[b],False);g,x=self.exchange(link.json()['url'].split('#token=')[1]);self.consent(g,x);upload=g.post(self.base+'/prospect-api.php?r=upload',data={'binding_id':b['id'],'request_key':secrets.token_hex(32)},files={'file':('SYNTHETIC-permission-paper.pdf',self.pdf(),'application/pdf')});self.assertEqual(upload.status_code,200,upload.text);self.must(self.own('import',upload_id=upload.json()['id'],confirm=True,reason='SYNTHETIC copy review'));b=self.lg('documents/'+str(b['id'])).json()['record'];self.must(self.action(b,'verify'))
  req=self.api('request-permission',{'id':int(p['record']['id']),'checksum':p['head']['checksum'],'binding_id':int(b['id'])});self.assertEqual(req.status_code,200,req.text);gid=int(req.json()['id']);self.assertEqual(self.api('permissions',s=old_guest,mode='prospect').json()['items'],[]);visible=self.api('permissions',s=g,mode='prospect');self.assertEqual(visible.status_code,200,visible.text);self.assertEqual(visible.json()['items'][0]['checksum'],p['head']['checksum']);decision={'id':gid,'checksum':p['head']['checksum'],'decision':'GRANTED','confirm':True,'reason':'SYNTHETIC independent voluntary grant'};self.assertEqual(self.api('decide',decision.copy()).status_code,403);self.assertEqual(self.api('decide',{**decision,'checksum':'0'*64},s=g,mode='prospect').status_code,422);self.assertEqual(self.api('decide',decision.copy(),s=g,mode='prospect').status_code,200);self.assertEqual(self.api('items',mode='public').json()['items'],[]);self.assertEqual(self.publish(p).status_code,200);self.assertEqual(len(self.api('items',mode='public').json()['items']),1)
  withdraw={**decision,'decision':'REVOKED','reason':''};self.assertEqual(self.api('decide',withdraw,s=g,mode='prospect').status_code,200);self.assertEqual(self.api('items',mode='public').json()['items'],[]);history=self.api('permissions',s=g,mode='prospect').json()['items'][0]['history'];self.assertEqual([e['action'] for e in history],['REQUESTED','GRANTED','PUBLISHED','REVOKED']);pub=self.api('items').json()['items'][0];self.assertEqual(self.publish({'record':pub,'head':pub['head']}).status_code,409)
  review=self.save(kind='review',order_id=oid,text='SYNTHETIC separate review needs its own permission');self.assertEqual(self.api('request-permission',{'id':int(review['record']['id']),'checksum':review['head']['checksum'],'binding_id':int(b['id'])}).status_code,409);private={'order_id':oid,'text':'SYNTHETIC customer original private review','display_name':'','confirm_private_submission':True,'request_key':secrets.token_hex(32)};before=self.f.sql('SELECT COUNT(*) n FROM nd_publications')[0]['n'];r=self.api('review-submit',private.copy(),s=g,mode='prospect');self.assertEqual(r.status_code,200,r.text);self.assertFalse(r.json()['published']);self.assertEqual(self.api('review-submit',private.copy(),s=g,mode='prospect').status_code,200);self.assertEqual(self.f.sql('SELECT COUNT(*) n FROM nd_publications')[0]['n'],before+1)
 def test_browser_owner_editing_and_actual_public_video(self):
  import os
  from playwright.sync_api import sync_playwright,expect
  video=(Path(__file__).parent/'fixtures/publication-synthetic.webm').read_bytes();r=self.owner.post(self.base+'/publication-api.php?mode=owner&r=upload',files={'file':('SYNTHETIC.webm',video,'video/webm')});self.assertEqual(r.status_code,200,r.text)
  with sync_playwright() as pw:
   browser=pw.chromium.launch(executable_path=os.environ.get('CHROMIUM_BIN','/usr/bin/chromium'),args=['--no-sandbox']);page=browser.new_page(viewport={'width':375,'height':812});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(self.base+'/studio.php');page.locator('#password').fill(self.f.password);page.locator('#login-form button').click();page.locator('#dashboard').wait_for(state='visible');page.goto(self.base+'/publication-owner.php');page.get_by_label('Название',exact=True).fill('SYNTHETIC browser video');page.get_by_label('Адрес: латиница, цифры и дефисы',exact=True).fill('synthetic-browser');page.get_by_label('Подробное описание / точный текст отзыва',exact=True).fill('SYNTHETIC <script>window.LEAK=true</script>');page.get_by_role('button',name='Сохранить приватную редакцию',exact=True).click();page.locator('#pub-editor details').get_by_text('Добавить из медиатеки / удалить неиспользуемые копии',exact=True).click();page.get_by_role('button',name='Добавить SYNTHETIC.webm',exact=True).click();page.get_by_role('heading',name='Элементов в смешанной галерее: 1',exact=True).wait_for();card=page.locator('#pub-records article').filter(has=page.get_by_role('heading',name='SYNTHETIC browser video',exact=True));card.get_by_label('Я владею правами на материалы; это мой демонстрационный проект без чужих данных',exact=True).check();card.get_by_label('Основание публикации',exact=True).fill('SYNTHETIC owner browser moderation');card.get_by_role('button',name='Опубликовать проверенную редакцию',exact=True).click();card.get_by_text('portfolio · PUBLISHED · редакция 2',exact=True).wait_for();page.goto(self.base+'/portfolio.php');page.get_by_role('heading',name='SYNTHETIC browser video',exact=True).wait_for();page.get_by_role('link',name='Открыть кейс и галерею →',exact=True).click();page.locator('video').wait_for();page.locator('video').evaluate('(v)=>v.load()');page.locator('video').evaluate('(v)=>new Promise(resolve=>{if(v.readyState>=1)resolve();else v.addEventListener("loadedmetadata",()=>resolve(),{once:true});})');self.assertGreater(page.locator('video').evaluate('(v)=>v.duration'),0);self.assertTrue(page.evaluate('window.LEAK===undefined'));self.assertFalse(page.evaluate('document.documentElement.scrollWidth>innerWidth'));self.assertEqual(errors,[]);browser.close()

